-- SQL: shape and rules live in the database.
-- Trade-off: strong invariants, but migrations are coordinated events.
CREATE TABLE orders (
  order_id   BIGINT PRIMARY KEY,
  user_id    BIGINT NOT NULL REFERENCES users(user_id),
  status     TEXT NOT NULL CHECK (status IN ('pending','paid','shipped')),
  total_cents INT NOT NULL CHECK (total_cents >= 0),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
-- One statement enforces a cross-row business question atomically.
BEGIN;
UPDATE accounts SET balance_cents = balance_cents - 5000 WHERE user_id = 42;
INSERT INTO orders(order_id, user_id, status, total_cents) VALUES (101, 42, 'paid', 5000);
COMMIT;

